mapper.select:
SELECT * FROM ( SELECT T1.COMPLAIN_ID, T1.DELEGATE_ID, T1.ACCOUNT_ID, T1.APPROVAL_STATUS_CD, T1.APPROVER_TYPE_CD, T1.PROCESS_DT, T1.APPROVAL_COMMENT, T1.SEQ_NO, T1.URL, T3.CATEGORY_CD, TC1.CODE_NAME AS CATEGORY_NAME, TC2.CODE_NAME AS APPROVAL_STATUS_NAME, TC3.CODE_NAME AS APPROVER_TYPE_NAME, TU.USER_NAME AS USER_NAME, ROW_NUMBER() OVER (ORDER BY T1.PROCESS_DT DESC, T1.SEQ_NO DESC) AS RNUM FROM T2000_APPROVAL_HISTORY T1 INNER JOIN T2000_COMPLAIN T2 ON T1.COMPLAIN_ID = T2.COMPLAIN_ID LEFT JOIN T2000_COMPLAIN_CATEGORY T3 ON T2.COMPLAIN_CATEGORY_ID = T3.COMPLAIN_CATEGORY_ID LEFT JOIN TOTAL_CODE TC1 ON T3.CATEGORY_CD = TC1.CODE_ID AND TC1.GROUP_ID = 'G0' LEFT JOIN TOTAL_CODE TC2 ON T1.APPROVAL_STATUS_CD = TC2.CODE_ID AND TC2.GROUP_ID = 'E0' LEFT JOIN TOTAL_CODE TC3 ON T1.APPROVER_TYPE_CD = TC3.CODE_ID AND TC3.GROUP_ID = 'F0' LEFT JOIN T1000_ACCOUNT TA ON T1.ACCOUNT_ID = TA.ACCOUNT_ID LEFT JOIN T1000_USER TU ON TA.USER_NO = TU.USER_NO
(T1.ACCOUNT_ID = #{accountId} OR T1.DELEGATE_ID = #{accountId})
AND T1.PROCESS_DT >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND T1.PROCESS_DT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND T1.APPROVAL_STATUS_CD = #{approvalStatusCd}
AND T3.CATEGORY_CD = #{categoryCd}
) WHERE RNUM BETWEEN #{startRow} AND #{endRow}

SELECT COUNT(*) FROM T2000_APPROVAL_HISTORY T1 INNER JOIN T2000_COMPLAIN T2 ON T1.COMPLAIN_ID = T2.COMPLAIN_ID LEFT OUTER JOIN T2000_COMPLAIN_CATEGORY T3 ON T2.COMPLAIN_CATEGORY_ID = T3.COMPLAIN_CATEGORY_ID WHERE ( T1.ACCOUNT_ID = #{accountId} OR T1.DELEGATE_ID = #{accountId})
AND T1.PROCESS_DT >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND T1.PROCESS_DT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND T1.APPROVAL_STATUS_CD = #{approvalStatusCd}
AND T3.CATEGORY_CD = #{categoryCd}
AND T1.APPROVAL_STATUS_CD = #{approvalStatusCd}

mapper.update:
UPDATE T2000_APPROVAL_HISTORY

    APPROVAL_STATUS_CD = #{approvalStatusCd},
    PROCESS_DT = SYSDATE,
    APPROVAL_COMMENT = #{approvalComment}


        DELEGATE_ID = #{delegateId}


WHERE
    COMPLAIN_ID = #{complainId}
    AND SEQ_NO = #{seqNo}
